package io.lumine.mythic.lib.skill;
import io.lumine.mythic.lib.api.player.MMOPlayerData; import io.lumine.mythic.lib.damage.AttackMetadata; import io.lumine.mythic.lib.player.PlayerMetadata; import io.lumine.mythic.lib.util.*; import net.minecraft.entity.*; import net.minecraft.util.math.Vec3d; import java.util.*;
public class SkillMetadata {
 public final SkillOrientation orientation; public static final List<String> RESERVED_VARIABLE_NAMES=List.of("caster","target","source");
 private final Skill cast; private final PlayerMetadata caster; private final Entity targetEntity; private final Vec3d sourceLocation,targetLocation; private final AttackMetadata attackSource; private final Map<String,Object> vars=new HashMap<>();
 public SkillMetadata(Skill cast,MMOPlayerData data){this(cast,data,null,null);} public SkillMetadata(Skill cast,MMOPlayerData data,Entity target,Vec3d targetLocation){this(cast,new PlayerMetadata(data),target,data.isOnline()?data.getPlayer().getPos():null,targetLocation,null,null);} public SkillMetadata(Skill cast,PlayerMetadata caster,Entity target,Vec3d source,Vec3d targetLocation,SkillOrientation orientation,AttackMetadata attack){this.cast=cast;this.caster=caster;this.targetEntity=target;this.sourceLocation=source;this.targetLocation=targetLocation;this.orientation=orientation;this.attackSource=attack;}
 public Skill getCast(){return cast;} public PlayerMetadata getCaster(){return caster;} public Vec3d getSourceLocation(){return sourceLocation;} public boolean hasAttackSource(){return attackSource!=null;} public AttackMetadata getAttackSource(){return attackSource;} public double getParameter(String id){return cast==null?0:cast.getParameter(id);} public Entity getTargetEntity(){if(targetEntity==null)throw new IllegalStateException("No target entity");return targetEntity;} public Entity getTargetEntityOrNull(){return targetEntity;} public LivingEntity getTargetLivingEntityOrNull(){return targetEntity instanceof LivingEntity l?l:null;} public boolean hasTargetEntity(){return targetEntity!=null;} public Vec3d getTargetLocation(){if(targetLocation==null)throw new IllegalStateException("No target location");return targetLocation;} public Vec3d getTargetLocationOrNull(){return targetLocation;} public boolean hasTargetLocation(){return targetLocation!=null;} public SkillOrientation getOrientation(){if(orientation==null)throw new IllegalStateException("No orientation");return orientation;} public SkillOrientation getOrientationOrNull(){return orientation;} public boolean hasOrientation(){return orientation!=null;} public Vec3d getSkillLocation(boolean target){return target&&targetLocation!=null?targetLocation:sourceLocation;} public Entity getSkillEntity(boolean target){return target&&targetEntity!=null?targetEntity:(caster!=null&&caster.isOnline()?caster.getPlayer():null);} public SkillOrientation getSkillOrientation(){return orientation;} public SkillMetadata clone(Vec3d target){return new SkillMetadata(cast,caster,targetEntity,sourceLocation,target,orientation,attackSource);} public SkillMetadata clone(Skill next){return new SkillMetadata(next,caster,targetEntity,sourceLocation,targetLocation,orientation,attackSource);} public SkillMetadata withCaster(PlayerMetadata next){return new SkillMetadata(cast,next,targetEntity,sourceLocation,targetLocation,orientation,attackSource);} public SkillMetadata withOrigin(Vec3d next){return new SkillMetadata(cast,caster,targetEntity,next,targetLocation,orientation,attackSource);} public SkillMetadata withTargetEntity(Entity next){return new SkillMetadata(cast,caster,next,sourceLocation,targetLocation,orientation,attackSource);} public SkillMetadata withTargetLocation(Vec3d next){return new SkillMetadata(cast,caster,targetEntity,sourceLocation,next,orientation,attackSource);} public String parseString(String input){if(input==null)return "";String out=input;for(var e:vars.entrySet())out=out.replace("<"+e.getKey()+">",String.valueOf(e.getValue()));return out;} public Object getVariable(String key){return vars.get(key);} public void setVariable(String key,Object value){if(value==null)vars.remove(key);else vars.put(key,value);} public static SkillMetadata of(MMOPlayerData d){return new SkillMetadata(null,d);} public static Lazy<SkillMetadata> lazyOf(MMOPlayerData d){return new Lazy<>(()->of(d));} public boolean hasAttackBound(){return attackSource!=null;} public AttackMetadata getAttack(){return attackSource;} public double getModifier(String key){return cast==null?0:cast.getModifier(key);} @Override public String toString(){return "SkillMetadata{"+(cast==null?"none":cast.toString())+",caster="+(caster==null?"none":caster.getUniqueId())+"}";}
}
